<?php $page_title='Inventory';require 'includes/header.php';$filter=$_GET['filter']??'';$where=$filter==='low'?"WHERE p.status='active' AND p.stock<=5":($filter==='out'?"WHERE p.stock=0":'');$products=$pdo->query("SELECT p.*,c.name category_name,COALESCE((SELECT SUM(oi.quantity) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.product_id=p.id AND o.order_status<>'cancelled'),0) sold_qty FROM products p LEFT JOIN categories c ON c.id=p.category_id $where ORDER BY p.stock ASC")->fetchAll();?>
<div class="page-head"><div><h1>Inventory</h1><p>Live stock levels and sold quantities.</p></div></div><?php if($filter==='low'):?><div class="alert">Showing products at or below the low-stock threshold of 5.</div><?php endif;?><div class="panel"><div class="table-wrap"><table><tr><th>Product</th><th>SKU / ID</th><th>Current stock</th><th>Sold quantity</th><th>Category</th><th>Price</th><th>Stock status</th><th></th></tr><?php foreach($products as $p):$ss=$p['stock']==0?'Out of Stock':($p['stock']<=5?'Low Stock':'In Stock');?><tr><td><strong><?=e($p['name'])?></strong></td><td>#<?=$p['id']?></td><td><strong><?=$p['stock']?></strong></td><td><?=$p['sold_qty']?></td><td><?=e($p['category_name']??'—')?></td><td><?=money(sale_price($p))?></td><td><span class="badge <?=$ss==='Out of Stock'?'cancelled':($ss==='Low Stock'?'processing':'delivered')?>"><?=$ss?></span></td><td><a class="btn light" href="products.php?edit=<?=$p['id']?>">Edit Product</a></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
